template <typename T = int, int Capacity = 10>
class Buffer {
    T data[Capacity];
public:
    Buffer() = default;
    T& operator[](int i) { return data[i]; }
    static constexpr int size = Capacity;
};

// Instantiation Examples (conceptual):
// Buffer<> b1;           // T=int, Capacity=10
// Buffer<float> b2;      // T=float, Capacity=10
// Buffer<char, 5> b3;    // T=char, Capacity=5
// Buffer<bool> b4;       // T=bool, Capacity=10
